#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-09-19
//
// Internal link graph for the docs site (docs/site/content/**/*.mdx).
// Emits an audit bundle under docs/audits/<name>/ with:
//   - link-graph.json       pages, per-page inbound/outbound counts, edge list
//   - orphans.json          pages with zero inbound links from other pages
//   - top-outbound.json     top 30 pages by outbound link count
//   - broken-links.json     in-scope /docs links that resolve to no page
//   - gsc-striking-distance.json  (only when a Search Console CSV is present)
//   - README.md             the same numbers in readable form
//
// Usage:
//   node scripts/seo/link-graph.mjs [--out docs/audits/seo-link-graph-YYYY-MM-DD]
//                                   [--gsc /path/to/gsc.csv]
//
// The graph builder is importable (buildLinkGraph) so the docs-site "Related
// pages" generator can reuse the exact same link-extraction rules at build time.

import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);
const { parseYamlFrontmatter } = require("../lib/parse-frontmatter.js");

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, "../..");
const CONTENT_DIR = path.join(ROOT, "docs/site/content");
const DEFAULT_GSC = "/tmp/sc31/gsc-orchestkit.csv";

// ---------------------------------------------------------------------------
// Page discovery + URL mapping (mirrors scripts/gen-docs-search-index.js so a
// URL here is the same string the search index and middleware use).
// ---------------------------------------------------------------------------

function walkMdx(dir) {
	const out = [];
	for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
		const full = path.join(dir, entry.name);
		if (entry.isDirectory()) out.push(...walkMdx(full));
		else if (entry.name.endsWith(".mdx")) out.push(full);
	}
	return out;
}

function stripRouteGroups(p) {
	return p
		.split("/")
		.filter((seg) => seg && !/^\(.*\)$/.test(seg))
		.join("/");
}

/** content/docs/<rel>.mdx -> /docs/<rel>; <dir>/index.mdx -> /docs/<dir>. */
export function urlForRelPath(relPath, slug) {
	if (slug) return `/docs/${String(slug).replace(/^\/+/, "")}`;
	let p = relPath.replace(/\\/g, "/").replace(/\.mdx$/, "");
	p = p.replace(/\/index$/, "").replace(/^index$/, "");
	p = stripRouteGroups(p);
	return p ? `/docs/${p}` : "/docs";
}

/** Route of the directory containing <relPath>; relative links resolve here. */
function dirUrlForRelPath(relPath) {
	const dir = path.dirname(relPath).replace(/\\/g, "/");
	if (dir === "." || dir === "") return "/docs";
	return `/docs/${stripRouteGroups(dir)}`;
}

// ---------------------------------------------------------------------------
// Link extraction. Two shapes carry links in this corpus:
//   - markdown:            [text](/docs/x)   (images `![` are not links)
//   - JSX/mdx attributes:  href="/docs/x"  href={'/docs/x'}  href={"/docs/x"}
// Everything else (src=, mailto:, external http(s), pure #anchors) is ignored.
// ---------------------------------------------------------------------------

const MD_LINK_RE = /(?<!!)\[[^\]\n]*\]\(\s*<?([^)\s>]+)>?[^)]*\)/g;
const JSX_HREF_RE =
	/\bhref\s*=\s*(?:\{\s*["'`]([^"'`]+)["'`]\s*\}|["'`]([^"'`]+)["'`])/g;

// Fenced code blocks (``` or ~~~, to the matching fence run or EOF) and
// inline `code` spans are not prose: regex or import examples inside them can
// carry [x](y) or href= text that is not a real link. In the 2026-09-19 audit
// they produced 26 of the 159 broken rows and 33 of the 44 non-docs rows.
// The closing fence must be the same marker char with length >= the opener:
// this corpus uses ```` fences precisely to hold nested ``` examples, which a
// loose `{3,}` closer would terminate early, while a same-char closer longer
// than the opener is valid per CommonMark.
const INLINE_CODE_RE = /`[^`\n]*`/g;
const FENCE_OPEN_RE = /^[ \t]*(`{3,}|~{3,})/;

function stripCode(body) {
	const out = [];
	let fence = null; // { ch, len } while inside a block
	for (const line of body.split("\n")) {
		if (fence === null) {
			const open = FENCE_OPEN_RE.exec(line);
			if (open) {
				fence = { ch: open[1][0], len: open[1].length };
				out.push("");
				continue;
			}
			out.push(line);
			continue;
		}
		const trimmed = line.trim();
		if (
			trimmed.length >= fence.len &&
			trimmed.split("").every((c) => c === fence.ch)
		) {
			fence = null;
		}
		out.push("");
	}
	return out.join("\n").replace(INLINE_CODE_RE, "");
}

function* rawHrefs(body) {
	const prose = stripCode(body);
	for (const m of prose.matchAll(MD_LINK_RE)) yield m[1];
	for (const m of prose.matchAll(JSX_HREF_RE)) yield m[1] ?? m[2];
}

function isExternal(href) {
	return /^(?:[a-z][a-z0-9+.-]*:|\/\/)/i.test(href);
}

/** Normalize an href to a site path, or null when it is not a page link. */
export function normalizeHref(href, baseDirUrl) {
	if (!href) return null;
	const clean = href.split("#")[0].split("?")[0];
	if (!clean) return null; // pure anchor or query
	if (isExternal(clean)) return null;

	let p;
	if (clean.startsWith("/")) {
		p = clean;
	} else {
		// Relative link: resolve against the directory route of the source page.
		const segs = `${baseDirUrl}/${clean}`.split("/");
		const resolved = [];
		for (const s of segs) {
			if (s === "" || s === ".") continue;
			if (s === "..") resolved.pop();
			else resolved.push(s);
		}
		p = `/${resolved.join("/")}`;
	}
	p = p.replace(/\.mdx$/i, "").replace(/\/index$/, "").replace(/\/+$/, "");
	return p === "" ? "/" : p;
}

// ---------------------------------------------------------------------------
// Graph builder (shared with docs-site generators).
// ---------------------------------------------------------------------------

/**
 * @param {{contentDir?: string}} opts
 * @returns {{
 *   pages: Map<string, {url:string,title:string,file:string,inbound:number,
 *     outbound:number,in:Set<string>,out:Set<string>}>,
 *   broken: {from:string,to:string}[],
 *   siteExternal: {from:string,to:string}[],
 * }}
 */
export function buildLinkGraph(opts = {}) {
	const contentDir = opts.contentDir ?? CONTENT_DIR;
	const docsRoot = path.join(contentDir, "docs");
	if (!fs.existsSync(docsRoot)) {
		throw new Error(`link-graph: content dir missing: ${docsRoot}`);
	}

	const files = walkMdx(docsRoot).sort();
	const pages = new Map();
	for (const file of files) {
		const rel = path.relative(docsRoot, file);
		const raw = fs.readFileSync(file, "utf8");
		const { frontmatter, body } = parseYamlFrontmatter(raw);
		const url = urlForRelPath(rel, frontmatter.slug);
		const heading = /^#\s+(.+)$/m.exec(body)?.[1]?.trim();
		pages.set(url, {
			url,
			title: String(frontmatter.title ?? heading ?? url),
			file: rel,
			inbound: 0,
			outbound: 0,
			in: new Set(),
			out: new Set(),
			_body: body,
			_base: dirUrlForRelPath(rel),
		});
	}

	const broken = [];
	const siteExternal = [];
	for (const page of pages.values()) {
		for (const href of rawHrefs(page._body)) {
			const target = normalizeHref(href, page._base);
			if (target === null) continue;
			if (target === page.url) continue; // self-links carry no link equity
			if (pages.has(target)) {
				page.out.add(target);
				pages.get(target).in.add(page.url);
			} else if (target.startsWith("/docs")) {
				broken.push({ from: page.url, to: target });
			} else {
				siteExternal.push({ from: page.url, to: target });
			}
		}
	}
	for (const page of pages.values()) {
		page.inbound = page.in.size;
		page.outbound = page.out.size;
		delete page._body;
		delete page._base;
	}
	return { pages, broken, siteExternal };
}

// ---------------------------------------------------------------------------
// Search Console join (optional). CSV columns: page,query,clicks,impressions,
// position. Pages at impression-weighted average position 8-20 are "striking
// distance": one ranking nudge from page 1, so they are the best targets for
// the inbound links this graph measures.
// ---------------------------------------------------------------------------

function parseCsvLine(line) {
	const out = [];
	let cur = "";
	let inQ = false;
	for (let i = 0; i < line.length; i++) {
		const c = line[i];
		if (inQ) {
			if (c === '"' && line[i + 1] === '"') {
				cur += '"';
				i++;
			} else if (c === '"') inQ = false;
			else cur += c;
		} else if (c === '"') inQ = true;
		else if (c === ",") {
			out.push(cur);
			cur = "";
		} else cur += c;
	}
	out.push(cur);
	return out;
}

function gscJoin(csvPath, pages) {
	const lines = fs.readFileSync(csvPath, "utf8").split(/\r?\n/).filter(Boolean);
	if (lines.length < 2) return [];
	const header = parseCsvLine(lines[0]).map((h) => h.trim().toLowerCase());
	const col = (name) => header.indexOf(name);
	const [ci, cq, cc, cim, cp] = ["page", "query", "clicks", "impressions", "position"].map(col);
	if (ci < 0 || cp < 0) return [];

	const byPage = new Map();
	for (const line of lines.slice(1)) {
		const cells = parseCsvLine(line);
		const pageUrl = cells[ci]?.trim();
		if (!pageUrl) continue;
		const key = pageUrl.replace(/^https?:\/\/[^/]+/i, "").replace(/\/+$/, "") || "/";
		const impressions = Number(cells[cim]) || 0;
		const position = Number(cells[cp]) || 0;
		const clicks = Number(cells[cc]) || 0;
		const agg = byPage.get(key) ?? { weighted: 0, impressions: 0, clicks: 0, queries: 0 };
		agg.weighted += position * Math.max(impressions, 1);
		agg.impressions += impressions;
		agg.clicks += clicks;
		agg.queries += 1;
		byPage.set(key, agg);
	}

	const rows = [];
	for (const [page, agg] of byPage) {
		const divisor = agg.impressions > 0 ? agg.impressions : agg.queries;
		const avg = agg.weighted / divisor;
		if (avg >= 8 && avg <= 20) {
			const entry = pages.get(page);
			rows.push({
				page,
				avgPosition: Number(avg.toFixed(2)),
				clicks: agg.clicks,
				impressions: agg.impressions,
				queries: agg.queries,
				inbound: entry?.inbound ?? null,
				title: entry?.title ?? null,
			});
		}
	}
	return rows.sort((a, b) => a.avgPosition - b.avgPosition || a.page.localeCompare(b.page));
}

// ---------------------------------------------------------------------------
// Emission.
// ---------------------------------------------------------------------------

function jsonOut(dir, name, value) {
	fs.writeFileSync(path.join(dir, name), `${JSON.stringify(value, null, 2)}\n`);
}

function renderReadme(d) {
	const lines = [];
	lines.push(`# SEO internal link graph, ${d.date}`);
	lines.push("");
	lines.push(`Built by \`scripts/seo/link-graph.mjs\` from \`docs/site/content\`.`);
	lines.push("");
	lines.push("## Totals");
	lines.push("");
	lines.push(`- Pages: **${d.pageCount}**`);
	lines.push(`- Internal links (deduped edges, self-links excluded): **${d.edgeCount}**`);
	lines.push(`- Orphan pages (0 inbound): **${d.orphans.length}**`);
	lines.push(`- Broken in-scope links (/docs target with no page): **${d.broken.length}**`);
	lines.push(`- Links to non-docs site paths (not counted): **${d.siteExternal.length}**`);
	lines.push("");
	lines.push("## Orphan pages");
	lines.push("");
	if (d.orphans.length === 0) lines.push("None.");
	else for (const o of d.orphans) lines.push(`- \`${o.url}\` ${o.title}`);
	lines.push("");
	lines.push("## Top 30 pages by outbound links");
	lines.push("");
	lines.push("| Page | Outbound | Inbound |");
	lines.push("| --- | ---: | ---: |");
	for (const p of d.topOutbound) {
		lines.push(`| \`${p.url}\` ${p.title} | ${p.outbound} | ${p.inbound} |`);
	}
	lines.push("");
	if (d.broken.length > 0) {
		lines.push("## Broken in-scope links");
		lines.push("");
		for (const b of d.broken) lines.push(`- \`${b.from}\` -> \`${b.to}\``);
		lines.push("");
	}
	lines.push("## Search Console join");
	lines.push("");
	if (d.gsc === null) {
		lines.push(
			`\`${d.gscPath}\` was not present when this audit ran; the position-8-to-20 join was skipped. Re-run with \`--gsc <csv>\` once a Search Console export (page, query, clicks, impressions, position) is available.`,
		);
	} else {
		lines.push(
			`Pages at impression-weighted average position 8-20 (from \`${d.gscPath}\`), with inbound counts:`,
		);
		lines.push("");
		lines.push("| Page | Avg position | Clicks | Impressions | Inbound |");
		lines.push("| --- | ---: | ---: | ---: | ---: |");
		for (const r of d.gsc) {
			lines.push(
				`| \`${r.page}\` ${r.title ?? ""} | ${r.avgPosition} | ${r.clicks} | ${r.impressions} | ${r.inbound ?? "n/a"} |`,
			);
		}
		if (d.gsc.length === 0) lines.push("");
		if (d.gsc.length === 0) lines.push("No pages landed in the 8-20 band.");
	}
	lines.push("");
	lines.push("## Files");
	lines.push("");
	lines.push("- `link-graph.json`: per-page title, inbound/outbound counts, edge list");
	lines.push("- `orphans.json`: zero-inbound pages");
	lines.push("- `top-outbound.json`: top 30 by outbound count");
	lines.push("- `broken-links.json`: /docs targets that resolve to no page");
	if (d.gsc !== null) lines.push("- `gsc-striking-distance.json`: the 8-20 join");
	lines.push("");
	return lines.join("\n");
}

function main(argv) {
	const args = { out: null, gsc: DEFAULT_GSC };
	for (let i = 2; i < argv.length; i++) {
		if (argv[i] === "--out") args.out = argv[++i];
		else if (argv[i] === "--gsc") args.gsc = argv[++i];
	}
	const outDir =
		args.out ?? path.join(ROOT, "docs/audits/seo-link-graph-2026-09-19");
	const date = /(\d{4}-\d{2}-\d{2})/.exec(outDir)?.[1] ?? "undated";

	const { pages, broken, siteExternal } = buildLinkGraph();
	const sorted = [...pages.values()].sort((a, b) => a.url.localeCompare(b.url));
	const orphans = sorted
		.filter((p) => p.inbound === 0)
		.map((p) => ({ url: p.url, title: p.title }));
	const topOutbound = [...pages.values()]
		.sort((a, b) => b.outbound - a.outbound || a.url.localeCompare(b.url))
		.slice(0, 30)
		.map((p) => ({ url: p.url, title: p.title, outbound: p.outbound, inbound: p.inbound }));

	const edges = [];
	for (const p of sorted) for (const to of [...p.out].sort()) edges.push({ from: p.url, to });

	const gscPresent = args.gsc ? fs.existsSync(args.gsc) : false;
	const gsc = gscPresent ? gscJoin(args.gsc, pages) : null;

	fs.mkdirSync(outDir, { recursive: true });
	jsonOut(outDir, "link-graph.json", {
		date,
		pageCount: pages.size,
		edgeCount: edges.length,
		pages: Object.fromEntries(
			sorted.map((p) => [
				p.url,
				{ title: p.title, file: p.file, inbound: p.inbound, outbound: p.outbound },
			]),
		),
		edges,
	});
	jsonOut(outDir, "orphans.json", orphans);
	jsonOut(outDir, "top-outbound.json", topOutbound);
	jsonOut(outDir, "broken-links.json", broken);
	if (gsc !== null) jsonOut(outDir, "gsc-striking-distance.json", gsc);

	const readme = renderReadme({
		date,
		pageCount: pages.size,
		edgeCount: edges.length,
		orphans,
		topOutbound,
		broken,
		siteExternal,
		gsc,
		gscPath: args.gsc,
	});
	fs.writeFileSync(path.join(outDir, "README.md"), readme);

	console.log(
		`link-graph: ${pages.size} pages, ${edges.length} edges, ` +
			`${orphans.length} orphans, ${broken.length} broken -> ${path.relative(ROOT, outDir)}`,
	);
	if (gsc === null) console.log(`link-graph: GSC CSV not found at ${args.gsc}; join skipped`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
	main(process.argv);
}
